from typing import List
class Solution:
    def displayTable(self, orders: List[List[str]]) -> List[List[str]]:
        column = ['Table']
        dish = []
        table_dict = {}
        for order_row in orders : 
            if order_row[-1] not in dish :
                dish.append(order_row[-1])

        for order_row in orders :
            if order_row[1] not in table_dict.keys() :
                table_dict[order_row[1]] = {}
                for food in dish : 
                    table_dict[order_row[1]][food] = 0 
                table_dict[order_row[1]][order_row[-1]] += 1
            else : 
               table_dict[order_row[1]][order_row[-1]] += 1 

        dish.sort()
        column = column + dish 
        ans = [column]
        table = []
        childDict = {}
        for key in sorted(table_dict.keys()) : 
            table.append(int(key))
            childDict[key] = []
            for value in column : 
                if value != 'Table' :
                    childDict[key].append(str(table_dict[key][value]))
        table.sort()
        output = [ans[0]]
        for table_num in table : 
            childList = [str(table_num)]
            output.append(childList + childDict[str(table_num)])
        return output

class Solution:
    def minNumberOfFrogs(self, croakOfFrogs: str) -> int:
        c = r = o = a = k = max_frog_croak = present_frog_croak = 0
        # need to know, at particular point,
        # what are the max frog are croaking,

        for i, v in enumerate(croakOfFrogs):
            if v == 'c':
                c += 1
				# c gives a signal for a frog
                present_frog_croak += 1
            elif v == 'r':
                r += 1
            elif v == 'o':
                o += 1
            elif v == 'a':
                a += 1
            else:
                k += 1
				# frog stop croaking
                present_frog_croak -= 1

            max_frog_croak = max(max_frog_croak, present_frog_croak)
            # if any inoder occurs;
            if c < r or r < o or o < a or a < k:
                return -1

        # if all good, else -1
        if present_frog_croak == 0 and c == r and r == o and o == a and a == k:
            return max_frog_croak
        return -1

class Solution:
    def maxDiff(self, num: int) -> int:
        num = str(num)

        i = next((i for i in range(len(num)) if num[i] != "9"), -1) #first non-9 digit
        hi = int(num.replace(num[i], "9"))

        if num[0] != "1": lo = int(num.replace(num[0], "1"))
        else: 
            i = next((i for i in range(len(num)) if num[i] not in "01"), -1)
            lo = int(num.replace(num[i], "0") if i > 0 else num)

        return hi - lo

